using namespace ofo;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
void quad(Geometry&g,Vec a,Vec b,Vec c,Vec d){Mesh m;m.vertices={{a},{b},{c},{d}};m.indices={0,1,2,0,2,3};g.meshes.push_back(m);}
Geometry road(bool wall=false,float height=0){Geometry g;g.materials.push_back({"road"});quad(g,{-100,height,-100},{-100,height,500},{100,height,500},{100,height,-100});if(wall)quad(g,{-100,height,45},{100,height,45},{100,height+10,45},{-100,height+10,45});return g;}
VehicleConfig car(){VehicleConfig c;c.mass=1000;c.inertia={1100,1200,250};c.lo={-.65f,.10f,-1.5f};c.hi={.65f,.7f,1.5f};c.center_mass={0,.28f,0};c.engine_torque=300;c.ratios={3,2,1.5f,1};c.torque_curve={{950,1},{7000,1}};for(int i=0;i<4;i++){auto&w=c.wheels[i];w.mount={i%2?.75f:-.75f,.15f,i<2?1.15f:-1.15f};w.rest=.32f;w.min=.05f;w.max=.55f;w.radius=.305f;w.k=22000;w.bump=1500;w.rebound=1800;}return c;}
int main(int argc,char**argv){try{
 auto c=car();Simulation s(road(),c,translate({0,1,0}));for(int i=0;i<300;i++)s.step({});Input drive;drive.throttle=1;drive.nitro=true;for(int i=0;i<50;i++)s.step(drive);auto before=s.state();s.recover();auto after=s.state();need(after.time==before.time&&after.nitro==before.nitro&&after.damage==before.damage,"Recovery preserves race time, nitro and damage");need(after.car==translate({0,1,0}),"Recovery must teleport without advancing physics");need(after.speed==0&&length(after.velocity)==0,"Recovery publishes stopped car");float spacer=s.diagnostics().at("handling").at("suspension_spacer_m");for(size_t i=0;i<4;i++){auto axle=point(after.car,c.wheels[i].mount-Vec{0,spacer,0});need(length(point(after.wheels[i],{})-axle)<1e-5f&&length(point(after.wheel_mounts[i],{})-axle)<1e-5f,"Recovery immediately publishes lifted wheel and hub transforms");}

 // Recovery itself must leave every other car untouched in the shared world.
 RaceOpponentConfig bot;bot.vehicle=c;bot.spawn=translate({15,1,0});RaceRoute route;route.points={{15,0,0},{15,0,100},{25,0,100},{25,0,0}};s.set_opponents({bot},route);for(int i=0;i<100;i++)s.step({});auto opponents=s.state().opponents;s.recover();need(s.state().opponents==opponents,"Recovery cannot advance opponent/world state");need(!s.recover((*opponents)[0].car),"Recovery rejects overlap with another car");
 Simulation elevated(road(false,5),c,translate({0,6,0}));for(int i=0;i<300;i++)elevated.step({});need(elevated.recover(translate({8,20,10})),"Authored route target can recover against actual track");need(elevated.state().car[13]>5&&elevated.state().car[13]<6,"Authored route Y=20 is ignored for road elevation");need(std::abs(elevated.state().car[12]-8)<1e-5f&&std::abs(elevated.state().car[14]-10)<1e-5f,"Recovery uses requested XZ");auto safe=elevated.state();need(!elevated.recover(translate({1000,0,1000})),"Missing ground rejects recovery");need(elevated.state().car==safe.car&&elevated.state().recovery_generation==safe.recovery_generation,"Failed recovery leaves state untouched");
 Simulation fallen(road(false,5),c,translate({0,-60,0}));need(fallen.recover(translate({8,20,10})),"Track-bounds fallback recovers a car fallen over 50m below road");need(fallen.state().car[13]>5&&fallen.state().car[13]<6,"Fallen car returns to actual track elevation");
 auto bridge=road(false,5);quad(bridge,{-100,9,-100},{-100,9,500},{100,9,500},{100,9,-100});Simulation lower_deck(bridge,c,translate({0,6,0}));need(lower_deck.recover(translate({8,20,10})),"Lower deck recovery");need(lower_deck.state().car[13]<6,"Recovery chooses road near previous elevation below an overpass");need(lower_deck.recover(translate({8,9.5f,10}),true),"An anchored route recovery can return to the upper deck");need(lower_deck.state().car[13]>9&&lower_deck.state().car[13]<10,"Departure anchor selects the original road height");
 Simulation controlled(road(),c,translate({0,1,0})),passive(road(),c,translate({0,1,0}));for(int i=0;i<300;i++){controlled.step({});passive.step({});}Input eject;eject.eject=true;controlled.step(eject);passive.step(eject);need(controlled.state().driver_ejected,"Manual ejection remains available");Input unoccupied;unoccupied.throttle=1;unoccupied.steer=1;unoccupied.nitro=true;for(int i=0;i<100;i++){controlled.step(unoccupied);passive.step({});}auto a=controlled.state(),b=passive.state();need(a.nitro==b.nitro&&!a.nitro_active&&a.steer==0,"Ejected driver cannot use steering or nitro");for(size_t i=0;i<16;i++)need(std::abs(a.car[i]-b.car[i])<1e-5f,"Ejected driver cannot propel the car");controlled.recover();controlled.step(eject);need(controlled.state().driver_ejected,"Manual ejection works again after recovery");controlled.recover();controlled.step(eject);need(!controlled.state().driver_ejected,"Held eject input cannot relaunch immediately after recovery");
 // Release adds a modest forward kick while preserving the initial pose.
 Simulation gentle(road(),c,translate({0,1,0}));for(int i=0;i<300;i++)gentle.step({});gentle.step(eject);auto launch=gentle.state();for(int i=0;i<20;i++)gentle.step({});auto flight=gentle.state();float advance=dot(point(flight.driver,{})-point(launch.driver,{}),unit(direction(launch.car,{0,0,1})));need(advance>.4f&&advance<1.1f,"Manual release has bounded 4m/s forward adapter, not a stationary drop or oversized launch");
 auto stunt_road=road();
 stunt_road.source="tracks/stunt/test";
 Simulation horizontal(stunt_road,c,translate({0,1,0}));
 for(int i=0;i<300;i++)horizontal.step({});
 Input level_launch=eject;
 level_launch.stunt_angle=0;
 horizontal.step(level_launch);
 const auto released=horizontal.state();
 for(int i=0;i<10;i++)horizontal.step({});
 const auto level_flight=horizontal.state();
 need(released.driver_ejected&&level_flight.driver[14]-released.driver[14]>.5f,"Zero-degree launch still carries the driver forward");
 need(level_flight.driver[13]-released.driver[13]<-.035f,"Zero-degree launch falls under gravity without a minimum upward angle");
 Simulation crash(road(true),c,translate({0,1,0}));for(int i=0;i<300;i++)crash.step({});Input full;full.throttle=1;full.nitro=true;float incoming=0;for(int i=0;i<1500&&!crash.state().driver_ejected;i++){incoming=crash.state().speed;crash.step(full);}need(crash.state().driver_ejected,"Serious frontal collision automatically ejects the player");need(incoming>12,"Crash ejection occurs at substantial incoming speed");std::cout<<"crash incoming="<<incoming<<" xyz="<<crash.state().car[12]<<","<<crash.state().car[13]<<","<<crash.state().car[14]<<" damage="<<crash.state().damage<<"\n";need(crash.recover(translate({0,20,0})),"Ejected race driver returns to grounded route");for(int i=0;i<100;i++)crash.step({});need(!crash.state().driver_ejected,"Old collision cannot trigger another ejection after return");

 auto derby_road=road();derby_road.source="data/tracks/derby/test";// Isolate catastrophic chassis impact from tire support and aerodynamic terminal velocity.
 // Roof-first contact makes destruction depend on a direct chassis impulse; an
 // upright landing can dissipate energy through suspension and need not destroy.
 auto derby_config=c;derby_config.drag={};Simulation destroyed(derby_road,derby_config,multiply(translate({0,300,0}),rotate_x(3.14159265f)));bool destruction_observed=false;float impact_speed=0;for(int i=0;i<1300;i++){auto before_impact=destroyed.state();destroyed.step({});auto after_impact=destroyed.state();if(before_impact.damage<1&&after_impact.damage>=1){destruction_observed=true;impact_speed=length(before_impact.velocity);need(!before_impact.driver_ejected&&after_impact.driver_ejected,"Derby destruction ejects driver in the same physics step");}}need(destruction_observed&&impact_speed>60,"Roof-first fixture must produce a real catastrophic impact before testing destruction ejection");std::cout<<"derby catastrophic speed="<<impact_speed<<" damage="<<destroyed.state().damage<<" ejected="<<destroyed.state().driver_ejected<<"\n";need(destroyed.state().damage>=1&&destroyed.state().driver_ejected,"Destroyed derby driver ejects");auto wreck=destroyed.state();need(!destroyed.recover(translate({10,0,0})),"Destroyed derby car cannot recover to route");destroyed.recover();need(destroyed.state().recovery_generation==wreck.recovery_generation&&destroyed.state().driver_ejected,"Legacy recover cannot revive a destroyed derby vehicle");
 if(argc>1){Resources resources(argv[1]);const std::string stage="tracks/forest/forest1/a";auto geometry=load_geometry(resources,stage_geometry(stage),stage);auto cfg=load_vehicle(resources,3);auto start=load_spawn(resources,stage);Simulation real(geometry,cfg,start);for(int i=0;i<200;i++)real.step({});Input boost;boost.throttle=1;boost.nitro=true;for(int i=0;i<20;i++)real.step(boost);auto original=real.state();CourseDirector director(race_course(resources,stage),1,1,0);CoursePose course_pose;course_pose.chassis=original.car;auto target=director.recovery_transform(course_pose);need(bool(target),"Native course provides nearest recovery route");need(real.recover(*target),"Native Forest1 road accepts route recovery with actual native vehicle");auto restored=real.state();need(restored.time==original.time&&restored.nitro==original.nitro&&restored.damage==original.damage,"Native recovery retains race time, nitro and damage");for(int i=0;i<60;i++)real.step({});need(real.state().car[13]>restored.car[13]-1.5f,"Native route recovery remains supported by actual track");std::cout<<"native recovery routeY="<<(*target)[13]<<" roadY="<<restored.car[13]<<"\n";auto native=load_native_driver(resources);btDefaultCollisionConfiguration config;btCollisionDispatcher dispatch(&config);btDbvtBroadphase broad;btSequentialImpulseConstraintSolver solver;btDiscreteDynamicsWorld world(&dispatch,&broad,&solver,&config);auto pose=sample_driver_pose(native,DriverPlacement{});auto transform=multiply(translate({3,4,5}),rotate_y(.6f));Vec reference=point(transform,{.2f,.3f,-.1f}),linear={2,3,4},angular={.3f,.7f,-.2f};btBoxShape car_shape(btVector3(3,3,3));btRigidBody::btRigidBodyConstructionInfo car_info(0,nullptr,&car_shape);btRigidBody owner(car_info),other_car(car_info);btTransform car_transform;car_transform.setFromOpenGLMatrix(transform.data());owner.setWorldTransform(car_transform);other_car.setWorldTransform(car_transform);world.addRigidBody(&owner,2,8);world.addRigidBody(&other_car,2,8);NativeDriverRagdoll rag(world,native,pose,transform,linear,angular,80,reference,&owner);need(rag.bodies().size()==11&&world.getNumConstraints()==10,"Original 11 bodies and 10 authored joints preserved");for(auto*body:rag.bodies()){need((body->getBroadphaseHandle()->m_collisionFilterMask&2)!=0,"Native driver collision mask permits other cars");need(!body->checkCollideWith(&owner)&&body->checkCollideWith(&other_car),"Driver ignores owner and permits other vehicles");auto p=body->getCenterOfMassPosition();Vec offset={p.x()-reference.x,p.y()-reference.y,p.z()-reference.z};auto expected=linear+cross(angular,offset);auto actual=body->getLinearVelocity();need(length(Vec{actual.x(),actual.y(),actual.z()}-expected)<1e-5f,"Ragdoll inherits angular point velocity about car COM");}world.performDiscreteCollisionDetection();bool hit_other_car=false;for(int i=0;i<dispatch.getNumManifolds();i++){auto*m=dispatch.getManifoldByIndexInternal(i);if(!m->getNumContacts())continue;need(m->getBody0()!=&owner&&m->getBody1()!=&owner,"Overlapping driver creates no owner contacts");hit_other_car=hit_other_car||m->getBody0()==&other_car||m->getBody1()==&other_car;}need(hit_other_car,"Native ragdoll creates real collision contacts with another car");world.removeRigidBody(&other_car);world.removeRigidBody(&owner);}
 std::cout<<"driver ejection/recovery passed\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
